import { bindle } from "@hobo/bindles";
import { waspApp } from "@hobo/wasp";

/**
 * Real Open SaaS (wasp-lang/open-saas) Bindle.
 * Docs: https://docs.opensaas.sh/ · deploy env: /guides/deploying/
 *
 * - db: self-host Postgres via OCI (or swap to b.external for BYO DATABASE_URL)
 * - web: waspApp(root) — ship runs `wasp` in that directory
 *
 * Optional SaaS keys (Stripe, S3, SendGrid, …) come from camp / b.external
 * connectors; discoverWaspEnv(root) lists them from .env.*.example.
 */
export default bindle((b) => {
	const db = b.container({
		image: "postgres:16-alpine",
		endpoints: { postgres: { port: 5432 } },
		env: {
			POSTGRES_USER: "wasp",
			POSTGRES_PASSWORD: "wasp",
			POSTGRES_DB: "OpenSaaS",
		},
	});
	const web = b.web(waspApp("examples/wasp-opensaas/app")).dependsOn(db);
	return { db, web };
});

import { bindle } from "@hobo/bindles";
import { convexApp } from "@hobo/convex";

/**
 * Real JamesCowling/swaghaus Bindle.
 * Upstream: https://github.com/JamesCowling/swaghaus · https://swaghaus.biz/
 *
 * - backend: official Convex self-host OCI (`ghcr.io/get-convex/convex-backend`)
 *   — Cloudflare Yard realizes as Workers Containers (not Convex Cloud, not laptop)
 * - auth: WorkOS AuthKit via b.external (Camp secretRef; fail-closed)
 * - web: convexApp(root) — ship pushes functions to the CF-hosted backend, then Vite
 */
export default bindle((b) => {
	const backend = b.container({
		image: "ghcr.io/get-convex/convex-backend:latest",
		endpoints: {
			api: { port: 3210 },
			httpActions: { port: 3211 },
		},
		env: {
			DISABLE_METRICS_ENDPOINT: "true",
		},
	});
	const auth = b.external({
		endpoints: { workos: "https://api.workos.com" },
	});
	const web = b
		.web(convexApp("examples/convex-swaghaus"))
		.dependsOn(backend, auth);
	return { backend, auth, web };
});

import { bindle } from "@hobo/bindles";
import { intent, trainable } from "@hobo/runtime";

type Todo = { id: string; text: string; completed: boolean };

@trainable
class Todos {
	@intent("List all todos")
	list(): { items: Todo[] } {
		return { items: [] };
	}

	@intent("Create a todo from text")
	create(text: string): Todo {
		return { id: "0", text, completed: false };
	}

	@intent("Toggle todo completed flag")
	toggle(id: string): Todo {
		return { id, text: "", completed: true };
	}
}

export default bindle((b) => {
	const todos = b.kv().allow("get", "set");
	return {
		todos,
		web: b.web(Todos).dependsOn(todos),
	};
});
